css:
.lg-root{position:absolute;left:64px;bottom:72px;display:flex;align-items:flex-end;font-family:var(--lg-font);}
.lg-avatar{width:var(--lg-avatar-size);height:var(--lg-avatar-size);border-radius:12px;overflow:hidden;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.25);backdrop-filter:blur(10px);display:flex;align-items:center;justify-content:center;flex:0 0 auto;}
.lg-avatar img{width:100%;height:100%;object-fit:cover;display:none;}
.lg-avatar img.is-ready{display:block;}
.lg-fallback{color:rgba(255,255,255,.4);font-size:34px;font-weight:700;}
.lg-avatar:has(img.is-ready) .lg-fallback{display:none;}
.lg-panel{background:rgba(20,20,24,.52);backdrop-filter:blur(18px) saturate(130%);border:1px solid rgba(255,255,255,.16);border-radius:12px;padding:14px 40px 15px 20px;min-width:320px;box-shadow:0 12px 36px rgba(0,0,0,.4);}
.lg-team{display:flex;align-items:center;gap:8px;margin-bottom:4px;}
.lg-team:not(:has(.lg-team-name:not(:empty),img.is-ready)){display:none;}
.lg-team-logo{position:relative;width:var(--lg-team-logo);height:var(--lg-team-logo);flex:0 0 auto;display:flex;align-items:center;justify-content:center;}
.lg-team-logo img{width:100%;height:100%;object-fit:contain;display:none;}
.lg-team-logo img.is-ready{display:block;}
.lg-team-fallback{width:6px;height:6px;background:var(--lg-accent);}
.lg-team-logo:has(img.is-ready) .lg-team-fallback{display:none;}
.lg-team-name{color:var(--lg-accent);font-size:var(--lg-team-size);font-weight:600;letter-spacing:1.5px;line-height:1.2;white-space:nowrap;max-width:420px;overflow:hidden;text-overflow:ellipsis;}
.lg-team-name:empty{display:none;}
.lg-name{color:#fff;font-size:var(--lg-name-size);font-weight:700;letter-spacing:.4px;line-height:1.12;white-space:nowrap;}
.lg-sub{color:rgba(255,255,255,.7);font-size:var(--lg-sub-size);font-weight:400;line-height:1.35;margin-top:3px;white-space:nowrap;min-height:1.35em;}
.lg-sub:empty{display:none;}
